ExprP V(const std::string& n){return std::make_unique<VarExpr>(n);} ExprP D(double n){return std::make_unique<DoubleLit>(n);}
ExprP B(const char*o,ExprP a,ExprP b){return std::make_unique<Binary>(o,std::move(a),std::move(b));}
ExprP C(const std::string&n){return std::make_unique<Call>(n);} ExprP C1(const std::string&n,ExprP a){auto c=C(n);c->args.push_back(std::move(a));return c;}
ExprP C2(const std::string&n,ExprP a,ExprP b){auto c=C(n);c->args.push_back(std::move(a));c->args.push_back(std::move(b));return c;}
ExprP C3(const std::string&n,ExprP a,ExprP b,ExprP d){auto c=C(n);c->args.push_back(std::move(a));c->args.push_back(std::move(b));c->args.push_back(std::move(d));return c;}
ExprP C4(const std::string&n,ExprP a,ExprP b,ExprP d,ExprP e){auto c=C(n);c->args.push_back(std::move(a));c->args.push_back(std::move(b));c->args.push_back(std::move(d));c->args.push_back(std::move(e));return c;}
ExprP C5(const std::string&n,ExprP a,ExprP b,ExprP d,ExprP e,ExprP f){auto c=C(n);c->args.push_back(std::move(a));c->args.push_back(std::move(b));c->args.push_back(std::move(d));c->args.push_back(std::move(e));c->args.push_back(std::move(f));return c;}
ExprP C6(const std::string&n,ExprP a,ExprP b,ExprP d,ExprP e,ExprP f,ExprP g){auto c=C(n);c->args.push_back(std::move(a));c->args.push_back(std::move(b));c->args.push_back(std::move(d));c->args.push_back(std::move(e));c->args.push_back(std::move(f));c->args.push_back(std::move(g));return c;}
StmtP Ret(ExprP e){auto s=std::make_unique<ReturnStmt>();s->value=std::move(e);return s;}
Method M(const char*r,const char*n,std::initializer_list<std::pair<const char*,const char*>> p){Method m;m.retType=r;m.name=n;m.body=std::make_unique<Block>();for(auto x:p)m.params.push_back({x.first,x.second});return m;}
void lowerExpr(ExprP&e){if(!e)return;if(auto*c=dynamic_cast<Call*>(e.get())){for(auto&a:c->args)lowerExpr(a);const std::string p="financial.";if(c->callee.rfind(p,0)==0){std::string n=c->callee.substr(p.size());static const std::set<std::string>a={"future_value","present_value","annuity_present","annuity_future","npv4","bond_price","bond_duration","capm","wacc","determinant2","solve2x2_x","solve2x2_y","quadratic_discriminant","quadratic_root_plus","quadratic_root_minus","ratio"};if(!a.count(n))throw std::runtime_error("Semantic error: unsupported executable financial call '"+c->callee+"'");c->callee="__native_financial_"+n;}return;}if(auto*b=dynamic_cast<Binary*>(e.get())){lowerExpr(b->lhs);lowerExpr(b->rhs);}else if(auto*u=dynamic_cast<Unary*>(e.get()))lowerExpr(u->operand);}
void lowerStmt(StmtP&s){if(!s)return;if(auto*v=dynamic_cast<VarDecl*>(s.get()))lowerExpr(v->init);else if(auto*a=dynamic_cast<Assign*>(s.get()))lowerExpr(a->value);else if(auto*e=dynamic_cast<ExprStmt*>(s.get()))lowerExpr(e->expr);else if(auto*p=dynamic_cast<PrintStmt*>(s.get()))lowerExpr(p->expr);else if(auto*r=dynamic_cast<ReturnStmt*>(s.get()))lowerExpr(r->value);else if(auto*b=dynamic_cast<Block*>(s.get()))for(auto&x:b->stmts)lowerStmt(x);else if(auto*i=dynamic_cast<IfStmt*>(s.get())){lowerExpr(i->cond);lowerStmt(i->thenS);lowerStmt(i->elseS);}else if(auto*w=dynamic_cast<WhileStmt*>(s.get())){lowerExpr(w->cond);lowerStmt(w->body);}else if(auto*f=dynamic_cast<ForStmt*>(s.get())){lowerStmt(f->init);lowerExpr(f->cond);lowerStmt(f->update);lowerStmt(f->body);}}
