void lowerProgram(Program&program){bool imported=false;for(const auto&m:program.imports)if(m=="financial")imported=true;if(!imported)return;bool helper=false;for(const auto&c:program.classes)if(c.name=="__NativeFinancial")helper=true;if(!helper)add(program);for(auto&c:program.classes){if(c.name=="__NativeFinancial")continue;for(auto&m:c.methods)for(auto&s:m.body->stmts)lowerStmt(s);for(auto&f:c.fields)lowerExpr(f.init);}}
